  bool isInterStateCustomer() {
  if (ledgerModel == null) return false;

  String customerCode = (ledgerModel!.stateCode ?? '').trim();
  String compCode = (companyStateCode).trim();

  if (customerCode.isEmpty || compCode.isEmpty) return false;

  return customerCode != compCode;
}
