        String formatMobileNumber(String mobileNo) {
          mobileNo = mobileNo.replaceAll(RegExp(r'\D'), ''); 

          if (mobileNo.length == 10) {
            return '91$mobileNo'; 
          } else if (mobileNo.length == 12 && mobileNo.startsWith('91')) {
            return mobileNo; 
          } else {
            return mobileNo; 
