        String formatMessage(String template, Map<String, dynamic> data) {
          RegExp regex = RegExp(r'#(.*?)#');

          return template.replaceAllMapped(regex, (match) {
            String key = match.group(1)!;
            
            return data.containsKey(key) ? data[key].toString() : match.group(0)!;
          });
        }

