 double parseLedgerBalance(String? balance) {
  if (balance == null || balance.isEmpty) return 0.0;

  final parts = balance.split(' ');
  double amount = double.tryParse(parts.first) ?? 0.0;

  if (parts.length > 1 && parts[1].toLowerCase() == 'cr') {
    return -amount;
  }

  return amount; 
}

  Future<String?> generateInvoicePDF() async {
    var taxSale = salesTypeData!.tax;
    var invoiceHead = salesTypeData!.type == 'SALES-ES'
        ? Settings.getValue<String>('key-sales-estimate-head', defaultValue: 'ESTIMATE')
        : salesTypeData!.type == 'SALES-Q'
            ? Settings.getValue<String>('key-sales-quotation-head', defaultValue: 'QUOTATION')
            : salesTypeData!.type == 'SALES-O'
                ? Settings.getValue<String>('key-sales-order-head', defaultValue: 'ORDER')
                : Settings.getValue<String>(
                    'key-sales-invoice-head', defaultValue: 'INVOICE');
    var otherAmount = dataW['otherAmount'];
    var dataLedger = dataW['ledger'][0];
    
    var ledger = dataLedger;
    List<dynamic> itemData = [];
    String salesManName = '';
    double subTotalQty = 0,
        subTotalCGST = 0,
        subTotalSGST = 0,
        subTotalIGST = 0,
        subTotalRate = 0,
        subTotalDiscount = 0,
        subTotalGross = 0,
        subTotalMrp = 0;

    if (dataInformationW['SalesMan'] != null && dataInformationW['SalesMan'].toString().isNotEmpty) {
      final salesManId = int.tryParse(dataInformationW['SalesMan'].toString());

      if (salesManId != null && salesManId > 0 && salesmanList.isNotEmpty) {
        final match = salesmanList.firstWhere(
          (e) => e.key == salesManId,
          orElse: () => null,
        );
        salesManName = match.value.toString();
      }
    }

    bool serialNoIsEmpty = false;
