      if (bytes != null && bytes.isNotEmpty) {
        final String fileName = 
            '${DateTime.now().millisecondsSinceEpoch.toString()}_.pdf';
        
        final Directory appDir = await getApplicationDocumentsDirectory();
        final String dirPath = '${appDir.path}/invoices';
        
        final Directory dir = Directory(dirPath);
        if (!await dir.exists()) {
          await dir.create(recursive: true);
        }
        
        final File file = File('$dirPath/$fileName');
        
        await file.writeAsBytes(bytes, flush: true);
        
        final fileExists = await file.exists();
        final fileLength = await file.length();
        
        debugPrint('Invoice PDF saved: ${file.path}');
        debugPrint('File exists: $fileExists, Size: $fileLength bytes');
        
        if (fileExists && fileLength > 0) {
          return file.path;
        }
      }
      return null;
    } catch (error) {
      debugPrint('Error generating invoice PDF: $error');
      return null;
    }
  }  


  Future<String> xFileToBase64(XFile file) async {
    try {
      final bytes = await file.readAsBytes();
      return base64Encode(bytes);
    } catch (e) {
      debugPrint('Error converting image to base64: $e');
      return '';
    }
  }

  Future<void> _addDeliveryDetails(String result,int type) async {
    try {
      List<Map<String, dynamic>> deliveryData = [];
      
      for (var item in deliveryItems) {
        String photoBase64 = await xFileToBase64(item.image);
        
        deliveryData.add({
          'id': int.tryParse(result.toString()) ?? 0,
          'fyId': currentFinancialYear!.id,
          'itemId': item.itemId ?? 0,
          'gridId': item.gId ?? 0,
          'photo': photoBase64,
          'type': type,
        });
      }
      
    api.addDeliveryDetialsOnItems(deliveryData).then((value) {
      if (value) {
      debugPrint('Delivery details inserted successfully');
    } else {
      debugPrint('Failed to insert delivery details');
    }
    });
      
    } catch (e) {
      debugPrint('Error in _addDeliveryDetails: $e');
    }
  }

  void showSnackBar(String message, {bool isError = false}) {
     Fluttertoast.showToast(
        msg: message,
        toastLength: Toast.LENGTH_LONG,
        gravity: ToastGravity.BOTTOM,
        timeInSecForIosWeb: 3,
        backgroundColor: isError ? Colors.red.shade700 : Colors.green.shade700,
        textColor: Colors.white,
        fontSize: 14.0,
      );
