Future<String> _createPDF(
  bool isLogo,
    int model,
    String title,
    CompanyInformation companySettings,
    List<CompanySettings> settings,
    var data,
    var customerBalance,
    isCashBill) async {
    
  return makePDF(isLogo, model, title, companySettings, settings, data, customerBalance,
  isCashBill)
      .then((value) => savePreviewPDF(value, title));
}

Future<String> savePreviewPDF(pw.Document pdf, var title) async {
  title = title.replaceAll(RegExp(r'[^\w\s]+'), '');
  if (kIsWeb) {
    try {
      // final bytes = await pdf.save();
      // final blob = html.Blob([bytes], 'application/pdf');
      // final url = html.Url.createObjectUrlFromBlob(blob);
      // final anchor = html.AnchorElement()
      //   ..href = url
      //   ..style.display = 'none'
      //   ..download = '$title.pdf';
      // html.document.body.children.add(anchor);
      // anchor.click();
      // html.document.body.children.remove(anchor);
      // html.Url.revokeObjectUrl(url);
      return '';
    } catch (ex) {
      ex.toString();
    }
    return '';
  } else {
    var output = await getTemporaryDirectory();
    final file = File('${'${output.path}/' + title}.pdf');
    await file.writeAsBytes(await pdf.save());
    return file.path.toString();
  }
}

