        showNotification(
          title: 'Sending Failed',
          body: 'Message failed: ${result['to']}',
          isSuccess: false,
        );
      }
    }).catchError((error) {
      showNotification(
        title: 'Sending Failed',
        body: 'Error: $error',
        isSuccess: false,
      );
    }).whenComplete(() {
      // setState(() {
