 Map<String, int> _parseSerialno(String serialno) {
  final Map<String, int> sizeQuantities = {};
  if (serialno.trim().isEmpty) return sizeQuantities; 

  final regex = RegExp(r'([\dA-Za-z]+)\s*:\s*(\d+)|([\dA-Za-z]+)');  
  final matches = regex.allMatches(serialno);

  for (final match in matches) {
    if (match.group(1) != null && match.group(2) != null) {
      
      final String size = match.group(1)!.trim(); 
      final int quantity = int.parse(match.group(2)!);
      sizeQuantities[size] = quantity;
    } else if (match.group(3) != null) {
      
      final String size = match.group(3)!.trim();
      sizeQuantities[size] = 1;
    }
  }

  return sizeQuantities;
}
String _rebuildSerialnoString(Map<String, int> sizeQuantities) {
  final serialnoParts = <String>[];
  sizeQuantities.forEach((size, quantity) {
    serialnoParts.add('$size: $quantity');
  });

  return serialnoParts.join(', ');
}
String _sumSerialnoQuantities(String currentSerialno, String newSerialno) {
  if (currentSerialno.isEmpty) return newSerialno;
  if (newSerialno.isEmpty) return currentSerialno;

  final Map<String, int> sizeQuantities = _parseSerialno(currentSerialno);
  final Map<String, int> newSizeQuantities = _parseSerialno(newSerialno);

  newSizeQuantities.forEach((size, quantity) {
    sizeQuantities.update(size, (value) => value + quantity, ifAbsent: () => quantity);
  });

  return _rebuildSerialnoString(sizeQuantities);
}
Map<String, int> _parseColorCounts(String colorString) {
  final Map<String, int> colorCounts = {};
  final regex = RegExp(r'([\w\s]+):\s*(\d+)'); 
  final matches = regex.allMatches(colorString);

  for (final match in matches) {
    final String? color = match.group(1)?.trim(); 
    final int count = int.parse(match.group(2)!);
    if (color != null) {
      colorCounts[color] = count;
    }
  }
  return colorCounts;
}
String _rebuildColorString(Map<String, int> colorCounts) {
  final colorParts = <String>[];
  colorCounts.forEach((color, count) {
    colorParts.add('$color: $count');
  });
  return colorParts.join(', ');
}

Map<String, Map<String, dynamic>> groupedData = {};

for (var item in dataParticulars) {
  final String key = '${item['itemId']}';
  final int itemQuantity = item['Qty'] ?? 1; // Get the item's quantity, default to 1 if null

  if (!groupedData.containsKey(key)) {
    // Create a new entry for this item
    groupedData[key] = {
      'itemId': item['itemId'],
      'itemname': item['itemname'],
      'COLOR': '${item['COLOR']} :- ${item['serialno']}: $itemQuantity', // Use itemQuantity here
      'serialno': '',
      'Qty': item['Qty'],
      'slno': item['slno'],
    };
  } else {
    // Get current color data
    String currentColorData = groupedData[key]!['COLOR'];
    Map<String, Map<String, int>> colorSizeMap = {};

    // Parse existing color data
    List<String> colors = currentColorData.split(' , ');
    for (String entry in colors) {
      List<String> parts = entry.split(' :- ');
      if (parts.length == 2) {
        String color = parts[0].trim();
        String sizeData = parts[1].trim();

        if (!colorSizeMap.containsKey(color)) {
          colorSizeMap[color] = {};
        }

        List<String> sizes = sizeData.split(', ');
        for (String sizeEntry in sizes) {
          List<String> sizeParts = sizeEntry.split(':');
          if (sizeParts.length == 2) {
