        pdf.addPage((pdfModel == 9 || pdfModel == 10 || pdfModel == 11)
       ? pw.Page(
                pageFormat: _pageFormat,
                build: (pw.Context context) {
                  double calculateEstTotalAmount(List<dynamic> perticu) {
                    return perticu.fold(
                        0,
                        (total, particular) =>
                            total + particular['Total'].toDouble());
                  }

                  double calculateEstTotalQuantity(List<dynamic> perticu) {
                    return perticu.fold(
                        0,
                        (total, particular) =>
                            total + particular['Qty'].toDouble());
                  }

                  int totalRowCount = pdfLineSpace > 0 ? pdfLineSpace : 25;
                  final int existingRowCount = dataParticulars.length;

                  final int emptyRowCount = totalRowCount - existingRowCount;
                  return pw.Column(children: [
                    _buildEstimateHeader(settings, companySettings, dataLedger,
                        dataInformation, printHeaderOnES),
                    pw.Container(
                      decoration: pw.BoxDecoration(border: pw.Border.all()),
                      child: pw.Table(
                        border: const pw.TableBorder(
                          horizontalInside: pw.BorderSide
                              .none, // Remove horizontal borders inside the table

                          verticalInside:
                              pw.BorderSide(), // Keep vertical borders
                        ),
                        columnWidths: const {
                          0: pw.FixedColumnWidth(15),
                          1: pw.FlexColumnWidth(20),
                          2: pw.FlexColumnWidth(10),
                          3: pw.FlexColumnWidth(10),
                          4: pw.FlexColumnWidth(10),
                          5: pw.FlexColumnWidth(20),
                        },
                        children: pdfItemRowsNonTax(
                            dataParticulars,
                            dataSerialNO,
                            emptyRowCount,
                            isPrintSerialNoInSales,
                            isQuantityBasedSerialNo,
                            isPrintSerialNoLineByLine),
                      ),
                    ),
                    pw.Container(
                      decoration: const pw.BoxDecoration(
                          color: pw.PdfColor.fromInt(0xFFCCCCCC),
                          border: pw.Border(
                              bottom: pw.BorderSide(),
                              left: pw.BorderSide(),
                              right: pw.BorderSide())),
                      child: pw.Table(
                        border: const pw.TableBorder(
                          horizontalInside: pw.BorderSide
                              .none, // Remove horizontal borders inside the table

                          verticalInside:
