_buildEstimateHeader(
    company, cSettings, dataLedger, dataInformation, bool isHeading) {
        var invoiceHead = salesTypeData!.type == 'SALES-ES'
      ? Settings.getValue<String>('key-sales-estimate-head', defaultValue: 'ESTIMATE')
      : salesTypeData!.type == 'SALES-Q'
          ? Settings.getValue<String>('key-sales-quotation-head', defaultValue: 'QUOTATION')
          : salesTypeData!.type == 'SALES-O'
              ? Settings.getValue<String>('key-sales-order-head', defaultValue: 'ORDER')
              : Settings.getValue<String>('key-sales-invoice-head', defaultValue: 'INVOICE');
  var companyState = ComSettings.getValue('COMP-STATE', company);
  var companyStateCode = ComSettings.getValue('COMP-STATECODE', company);
  var companyTaxNo = ComSettings.getValue('GST-NO', company);
  return pw.Column(children: [
    isHeading
        ? pw.Container(
            padding: const pw.EdgeInsets.all(10),
            height: 100,
            width: double.infinity,
