_addOtherAmountNeww(List otherAmount) {
  return otherAmount.isNotEmpty && checkOtherAmountHaveValue(otherAmount)
      ? pw.Table(
          // border: pw.TableBorder.all(width: 0.2),
          defaultColumnWidth: const pw.IntrinsicColumnWidth(),
          children: [
              for (var i = 0; i < otherAmount.length; i++)
                pw.TableRow(children: [
                  pw.Column(children: [
                    pw.Row(
                      mainAxisAlignment: pw.MainAxisAlignment.end,
                      children: [
                        pw.Text(
                          '${otherAmount[i]['LedName'] + ' : ' + otherAmount[i]['Amount'].toStringAsFixed(2)}  ',
                          style: pw.TextStyle(
                              fontSize: 3, fontWeight: pw.FontWeight.bold),
                        ),
                      ],
                    ),
                  ])
                ]),
            ])
      : pw.Container(
          height: 15,
          decoration: const pw.BoxDecoration(
            border: pw.Border(
              // top: BorderSide(color: Colors.black, width: 2),
              right: pw.BorderSide(
                color: pw.PdfColor.fromInt(0xFF000000),
              ),
              bottom: pw.BorderSide(
                color: pw.PdfColor.fromInt(0xFF000000),
              ),
            ),
          ),
        );
}

