pw.Widget _buildFooter(pw.Context context) {
  debugPrint('Page ${context.pageNumber}/${context.pagesCount}');
  return pw.Row(
    mainAxisAlignment: pw.MainAxisAlignment.spaceBetween,
    crossAxisAlignment: pw.CrossAxisAlignment.end,
    children: [
      pw.Container(),
      pw.Text(
        'Page ${context.pageNumber}/${context.pagesCount}',
        style: const pw.TextStyle(
          fontSize: 12,
          color: PdfColors.grey,
        ),
      ),
    ],
  );
}

pw.PageTheme _buildTheme(PdfPageFormat pageFormat) {
  return pw.PageTheme(
    pageFormat: pageFormat,
    buildBackground: (context) => pw.Container(
      decoration: pw.BoxDecoration(
        color: PdfColors.white,
        border: pw.Border.all(width: 1, color: PdfColors.black),
      ),
    ),
    orientation: pw.PageOrientation.portrait,
    // margin: pw.EdgeInsets.all(10),
    // theme: pw.ThemeData.withFont(
    //   base: base,
    //   bold: bold,
    //   italic: italic,
    // ),
  );
}

_addOtherAmountPDF(var dataAmount) {
  // bool isData = true;
  return dataAmount.length > 0
      ? pw.Table(
          // border: pw.TableBorder.all(width: 0.2),
          defaultColumnWidth: const pw.IntrinsicColumnWidth(),
          children: [
              for (var i = 0; i < dataAmount.length; i++)
                pw.TableRow(children: [
                  pw.Column(children: [
                    pw.Row(
                      mainAxisAlignment: pw.MainAxisAlignment.end,
                      children: [
                        pw.Text(dataAmount[i]['LedName'] +
                            ' : ' +
                            dataAmount[i]['Amount'].toStringAsFixed(2)),
                      ],
                    ),
                  ])
                ]),
            ])
      : pw.Table(
          // border: pw.TableBorder.all(width: 0.2),
          defaultColumnWidth: const pw.IntrinsicColumnWidth(),
          children: [
              pw.TableRow(children: [
                pw.Column(children: [
                  pw.Row(
                    mainAxisAlignment: pw.MainAxisAlignment.end,
                    children: [
                      pw.Text('Discount : 0.00'),
                    ],
                  ),
                ])
              ]),
            ]);
}

_addOtherAmountPDFNew(var dataAmount) {
  // bool isData = true;
  return dataAmount.length > 0 && checkOtherAmountHaveValue(dataAmount)
      ? pw.Table(
          // border: pw.TableBorder.all(width: 0.2),
          defaultColumnWidth: const pw.IntrinsicColumnWidth(),
          children: [
              for (var i = 0; i < dataAmount.length; i++)
                pw.TableRow(children: [
                  pw.Column(children: [
                    pw.Row(
                      mainAxisAlignment: pw.MainAxisAlignment.end,
                      children: [
                        pw.Text(dataAmount[i]['LedName'] +
                            ' : ' +
                            dataAmount[i]['Amount'].toStringAsFixed(2)),
                      ],
                    ),
                  ])
                ]),
            ])
      : pw.Container(
          height: 15,
          decoration: const pw.BoxDecoration(
            border: pw.Border(
              // top: BorderSide(color: Colors.black, width: 2),
              right: pw.BorderSide(
                  color: PdfColor.fromInt(0xFF000000), // Black color,
                  width: 1),
              bottom: pw.BorderSide(
                  color: PdfColor.fromInt(0xFF000000), // Black color,
                  width: 1),
            ),
          ),
        );
}

bool checkOtherAmountHaveValue(otherAmount) {
  bool ret = false;
  for (var i = 0; i < otherAmount.length; i++) {
    if (otherAmount[i]['Amount'].toDouble() > 0) {
      ret = true;
      break;
    }
  }
  return ret;
}

