 bool entryNoLoading = false;

getEntryNo(saleFormId) {
  setState(() {
    entryNoLoading = true;
  });
  if (!hasUserModifiedEntry) {
    api.getSalesInvoiceNo(saleFormId, 'SEntryNo').then((value) {
      setState(() {
        entryNo = (int.parse(value.toString()) + 1).toString();
        entryNoController.text = entryNo;
        entryNoLoading = false;
      });
    });
  }
}

  selectSalesType() {
    return ListView.builder(
      shrinkWrap: true,
      itemCount: isCustomForm ? salesTypeDisplay.length : salesTypeList.length,
      itemBuilder: (context, index) {
        return _listSalesTypItem(index);
      },
    );
  }

  _listSalesTypItem(index) {
    return Column(
      children: [
        InkWell(
          child: Container(
            decoration: BoxDecoration(
                borderRadius: BorderRadius.circular(3),
                border: Border.all(color: grey)),
            child: ListTile(
                title: Text(
              isCustomForm
                  ? salesTypeDisplay[index].name
                  : salesTypeList[index].name,
              style: const TextStyle(fontFamily: 'poppins'),
            )),
          ),
          onTap: () {
            setState(() {
              salesTypeData =
                  isCustomForm ? salesTypeDisplay[index] : salesTypeList[index];
              previewData = true;
              taxable = isTaxTypeLocked
                  ? isTaxTypeLocked
                  : (salesTypeData != null ? salesTypeData!.tax : taxable);
              rateTypeItem = rateTypeList.isEmpty
                  ? null
                  : rateTypeList.firstWhere((element) =>
                      element.name == salesTypeData!.rateType.toUpperCase());
              if(keyLocationFromSForms){
                lId = salesTypeData!.location;
              }        
              getEntryNo(salesTypeData!.id);
                if(companySettings!.customerCode == "MOOCHIKUNDIL@TRADERS"){
                  String transactionType = '';
                    if (salesTypeData!.type == 'SALES-BC') {
                      transactionType = 'PDF-BC';
                    } else if (salesTypeData!.type == 'SALES-BB') {
                      transactionType = 'PDF-BB';
                    } else { 
                    }
                  if (printSettingsList.isNotEmpty) {
                    printSettingsModel = printSettingsList.firstWhere(
                        (element) =>
                            element.model == 'INVOICE DESIGNER' &&
                            element.dTransaction == transactionType &&
                            element.fyId == currentFinancialYear!.id,
                        orElse: () => printSettingsList.isNotEmpty
                            ? printSettingsList[0]
                            : PrintSettingsModel.empty());
                  }
                }else{
                  if (printSettingsList != null) {
                  if (printSettingsList.isNotEmpty) {
                    printSettingsModel = printSettingsList.firstWhere(
                        (element) =>
                            element.model == 'INVOICE DESIGNER' &&
                            element.dTransaction == salesTypeData!.type &&
                            element.fyId == currentFinancialYear!.id,
                        orElse: () => printSettingsList.isNotEmpty
                            ? printSettingsList[0]
                            : PrintSettingsModel.empty());
                  }
                }
                }
            });
          },
        ),
        const SizedBox(
          height: 10,
        )
      ],
    );
  }

