// }
 fetchProductData(String itemNameLike) async {
  setState(() {
    asyncLoading = true; // Show loading
  });
  try {
    final result = (salesTypeData!.type == 'SALES-O' || salesTypeData!.type == 'SALES-Q')
        ? (!isStockProductOnlyInSalesQO
            ? await api.fetchStockProductLike(DateUtil.dateDMY2YMD(formattedDate), itemNameLike)
            : await api.fetchNoStockProductLike(DateUtil.dateDMY2YMD(formattedDate), itemNameLike))
        : await api.fetchStockProductLike(DateUtil.dateDMY2YMD(formattedDate), itemNameLike);

    return result;
  } finally {
    setState(() {
      asyncLoading = false; // Hide loading
    });
  }
}  

