                                      cartItem[position!].cdPer = cdPer;
                                      cartItem[position!].cDisc = cDisc;
                                      cartItem[position!].net = subTotal;
                                      cartItem[position!].cess = cess;
                                      cartItem[position!].total = total;
                                      cartItem[position!].profitPer =
                                          profitPer;
                                      cartItem[position!].fUnitValue =
                                          fUnitValue;
                                      cartItem[position!].adCess = adCess;
                                      cartItem[position!].iGST = iGST;
                                      cartItem[position!].cGST = csGST;
                                      cartItem[position!].sGST = csGST;
                                      cartItem[position!].stock =
                                          selectedVariant!.quantity!;
                                      cartItem[position!].color = selectedColor;   
                                      cartItem[position!].size = selectedSize?.toInt();
                                      cartItem[position!].remark = _remarkController.text;
                                      // cartItem[position!].deliveryDate = formattedItemDeliveryDate;
                                     }      
                                      editItem = false;
                                      calculateTotal();
                                     }
                                    } 
                                    else {
                                      if (quantity <= 0) {
                                        Fluttertoast.showToast(msg: '0 Quantity Not Allowed');
                                      }
                                      else{
                                      addProduct(
                                          CartItem(
                                              id: totalItem + 1,
                                              itemId:
                                                  selectedVariant!.itemId!,
                                              itemName:
                                                  selectedVariant!.name!,
                                              quantity: quantity,
                                              rate: rate,
                                              rRate: rRate,
                                              uniqueCode: uniqueCode,
                                              gross: gross,
                                              discount: discount,
                                              discountPercent:
                                                  discountPercent,
                                              rDiscount: rDisc,
                                              fCess: kfc,
                                              serialNo:
                                                  _serialNoController.text,
                                              tax: tax,
                                              taxP: taxP,
                                              unitId: _dropDownUnit,
                                              unitValue: unitValue ?? 1,
                                              pRate: pRate,
                                              rPRate: rPRate,
                                              barcode: barcode,
                                              expDate: expDate,
                                              free: freeQty,
                                              fUnitId: fUnitId,
                                              cdPer: cdPer,
                                              cDisc: cDisc,
                                              net: subTotal,
                                              cess: cess,
                                              total: total,
                                              profitPer: profitPer,
                                              fUnitValue: fUnitValue,
                                              adCess: adCess,
                                              iGST: iGST,
                                              cGST: csGST,
                                              sGST: csGST,
                                              stock:
                                                  selectedVariant!.quantity!,
                                              minimumRate: selectedVariant!
                                                  .minimumRate!,
                                                  adCessPer: adCessPer,
                                                  cessPer: cessPer,
                                               color: selectedColor ?? -1,
                                               size: selectedSize!.toInt() ?? -1,
                                              // remark:     
                                                  ),
                                          -1);
                                      }
                                    }
                                  } else {
                                    ScaffoldMessenger.of(context)
                                        .showSnackBar(SnackBar(
                                      content:
                                          const Text('Please select Unit'),
                                      duration: const Duration(seconds: 1),
                                      action: SnackBarAction(
                                        label: 'Click',
                                        onPressed: () {
                                          // print('Action is clicked');
                                        },
                                        textColor: Colors.white,
                                        disabledTextColor: Colors.grey,
                                      ),
                                      backgroundColor: Colors.red,
                                    ));
                                  }
                                } else {
                                  ScaffoldMessenger.of(context)
                                      .showSnackBar(SnackBar(
                                    content: const Text(
                                        'Sorry Non Profitable Rate.'),
                                    duration: const Duration(seconds: 1),
                                    action: SnackBarAction(
                                      label: 'Click',
                                      onPressed: () {
                                        // print('Action is clicked');
                                      },
                                      textColor: Colors.white,
                                      disabledTextColor: Colors.grey,
                                    ),
                                    backgroundColor: Colors.red,
                                  ));
                                }
                                // }
                              }
                              }
                            }
                          }
                          if (quantity > 0) {
                            debugPrint("unit ==== ${unitValue.toString()}");
                            clearValue();
                            balanceCalculate();
                           netBalanceCalculate();
                            nextWidget = 0;
                          }
                        });
                        }else{
                          Fluttertoast.showToast(
                            backgroundColor: red,
                            msg: 'Product Not Found'
                            );
                        }
                       },);
                      },
                      child: Container(
                        height: 60,
                        color: kPrimaryColor,
                        child:  Center(
                          child: Text(
                            editItem?'Edit': 'Save',
                            style: const TextStyle(
                              fontFamily: 'Poppins',
                              fontSize: 16,
                              fontWeight: FontWeight.w500,
                              color: Colors.white,
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
              ],
            ),
          )),
    );
  }

