                                final filteredItems = deliveryItems.where((item) => item.itemId == (editItem ? cartModel!.itemId! : selectedVariant!.itemId)).toList();
                                final item = filteredItems[index];
                                
                                if (item.image == null) return const SizedBox();
                                return Stack(
                                  children: [
                                    InkWell(
                                      onTap: () {
                                        List<XFile> allImages = filteredItems
                                            .where((element) => element.image != null)
                                            .map((e) => e.image!)
                                            .toList();
                                        int galleryIndex = allImages.indexOf(item.image!);
                                        if (galleryIndex != -1) {
                                          Navigator.push(
                                            context,
                                            MaterialPageRoute(
                                              builder: (_) => FullGalleryViewer(
                                                images: allImages,
                                                initialIndex: galleryIndex,
