                                                  setState(() {
                                                    var itemToRemove = filteredItems[deleteIndex];
                                                    deliveryItems.removeWhere(
                                                      (item) => item.image == itemToRemove.image && 
                                                              item.itemId == (editItem ? cartModel!.itemId! : selectedVariant!.itemId)
                                                    );
                                                  });
