 codeWiseSimpleField(){
  return InkWell(
    child: Container(
      decoration: BoxDecoration(
        border: Border.all(color: Colors.grey),
        borderRadius: BorderRadius.circular(5),
      ),
      child: TypeAheadField(
        controller: itemNameControl,
        decorationBuilder: (context, child) {
          return Material(
            child: child,
          );
        },
        builder: (context, controller, focusNode) {
          return TextField(
            enabled: !editItem,
            controller: controller,
            focusNode: focusNode,
            decoration: InputDecoration(
              border: InputBorder.none,
              suffixIcon: !editItem ? Visibility(
                visible: enableBarcode,
                child: IconButton(
                  onPressed: () {
                    searchProductBarcode();
                  },
                  icon: Image.asset('assets/icons/ic_barcode_scanner_new.png', scale: 2.6),
                ),
              ) : SizedBox(),
            ),
          );
        },
        loadingBuilder: (context) => Center(child: const CircularProgressIndicator()),
        
        emptyBuilder: (context) => SizedBox.shrink(), 
        
        // emptyBuilder: (context) => Container(
        //   padding: EdgeInsets.all(16),
        //   child: Text('Start typing to search...', style: TextStyle(color: Colors.grey)),
        // ),
        
        // suggestionsCallback: (pattern) async {
        //   if (pattern.isEmpty) {
        //     return <String>[]; 
        //   }
          
        //   try {
        //     final data = await api.getSalesListDataLike(pattern, 'sales_list/ItemCodeLike');
        //     itemNameListDisplay = data;
            
        //     final names = itemNameListDisplay!
        //         .map((item) => item.name)
        //         .where((name) => name != null)
        //         .cast<String>()
        //         .toList();
            
        //     // Solution 4: Always return at least something if you don't want empty state
        //     // if (names.isEmpty) {
        //     //   return <String>['No matching items']; 
        //     // }
            
        //     return names;
        //   } catch (e) {
        //     return <String>[];
        //   }
        // },
        
         suggestionsCallback: (pattern) async {
          if (itemStockAll == true) {
            try {
              final allData =  (salesTypeData!.type == 'SALES-O' ||
                salesTypeData!.type == 'SALES-Q')
            ? isStockProductOnlyInSalesQO
                ? await api.fetchStockProduct(DateUtil.dateDMY2YMD(formattedDate))
                : await api.fetchNoStockProduct(DateUtil.dateDMY2YMD(formattedDate))
            : noStockItemsOnSales
             ? await api.fetchNoStockProduct(DateUtil.dateDMY2YMD(formattedDate))
             : await api.fetchStockProduct(DateUtil.dateDMY2YMD(formattedDate));
              // api.fetchNoStockProduct(DateUtil.dateDMY2YMD(formattedDate));
              
              if (allData != null && allData.isNotEmpty) {
                List<StockItem> filteredItems = allData
                    .where((item) => 
                        item.code?.toLowerCase().contains(pattern.toLowerCase()) ?? false ||
                        item.name!.toLowerCase().contains(pattern.toLowerCase()) ?? false)
                    .toList();
                return filteredItems;
              }
            } catch (e) {
              print('Error fetching all items: $e');
            }
          }
          if (pattern.isEmpty) {
            return <String>[]; 
          }
          
          try {
            final data = await api.getSalesListDataLike(pattern, 'sales_list/ItemCodeLike');
            itemNameListDisplay = data;
            
            final names = itemNameListDisplay!
                .map((item) => item.name)
                .where((name) => name != null)
                .cast<String>()
                .toList();
            
            return names;
          } catch (e) {
            return <String>[];
          }
        },
        // itemBuilder: (context, suggestion) {
        //   return ListTile(
        //     title: Text(
        //       suggestion.toString(),
        //       style: const TextStyle(
        //         fontFamily: 'poppins',
        //         fontSize: 16,
        //       ),
        //     ),
        //   );
        // },
        itemBuilder: (context, suggestion) {
          if (suggestion is StockItem) {
            return ListTile(
              title: Text(
                "${suggestion.code} ${suggestion.name}",
                style: const TextStyle(
                  fontFamily: 'poppins',
                  fontSize: 16,
                  // fontWeight: FontWeight.bold,
                ),
              ),
              subtitle: Text(
                "Qty: ${suggestion.quantity}",
                style: const TextStyle(
                  fontFamily: 'poppins',
                  fontSize: 14,
                  color: Colors.grey,
                ),
              ),
            );
          } else {
            return ListTile(
              title: Text(
                suggestion.toString(),
                style: const TextStyle(
                  fontFamily: 'poppins',
                  fontSize: 16,
                ),
              ),
            );
          }
        },
        
        onSelected: (dynamic value) async {
          lastRateStatus = true;
          String itemId;
          String itemName;
          // String sanitizedValue = RegExp(r'^[^ ,\-]+').stringMatch(value) ?? '';
          // itemNameLike = sanitizedValue.substring(0, sanitizedValue.length < 5 ? sanitizedValue.length : 5);
          if(itemStockAll == true && value is StockItem){
            itemId = value.code!;
            itemName = value.name!;
          }else{
           itemId = value;
          }
          setState(() {
            isItemsLoading = true;
          });
          
          try {
            final responds = noStockItemsOnSales
             ? await api.fetchProductByItemCode(itemId,taxGroupUpdate)
             : await api.fetchStockByItemCode(itemId,taxGroupUpdate);
            if (responds != null && responds.isNotEmpty) {
              var res = responds[0];
              setState(() {
                isItemsLoading = false;
                selectedItem = StockItem(
                  code: itemId,
                  hasVariant: responds.length > 1 ? true : false,
                  id: res.itemId,
                  name: res.name,
                  quantity: res.quantity
                );
                // _quantityController.text = '';
                itemNameControl.text = selectedItem.name!;
                selectedItemId = selectedItem.id;
                selectedItemCode = selectedItem.code;
              });
            } else {
              setState(() {
                isItemsLoading = false;
              });
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(content: Text('No item found with this code')),
              );
              return;
            }
          } catch (e) {
            setState(() {
              isItemsLoading = false;
            });
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(content: Text('Error fetching item: ${e.toString()}')),
            );
            return;
          }
          if (sherTex) {
            if (selectedItem.quantity > 0) {
              setState(() {
                isLoading = true;
              });
              try {
                var newValue;
                _dropDownUnit = 0;
                rate = 0;
                quantity = 0;
                _quantityController.text = '';
                _discountController.text = '';
                _discountPercentController.text = '';
                tax = 0;
                _rateController.text = '';
                _serialNoController.text = '';
                discount = 0;
                discountPercent = 0;
                subTotal = 0;
                total = 0;
                gross = 0;
                selectedColor = null;
                selectedSize = null;
                var datas = api.fetchStockVariantList(selectedItemId!,taxGroupUpdate,lId).then((value) {
                  setState(() {
                    isLoading = false;
                  });
                  return showSherTexItemDialog(context, value, isSerialNoInStockVariant, selectedItem.name, selectedItem.quantity, []);
                });
              } catch (e) {
                setState(() {
                  isLoading = false;
                });
                ScaffoldMessenger.of(context).showSnackBar(
                  SnackBar(content: Text('Error fetching stock variants: ${e.toString()}')),
                );
              }
            } else {
              setState(() {
                isLoading = true;
              });
              try {
                var newValue;
                _dropDownUnit = 0;
                rate = 0;
                quantity = 0;
                _quantityController.text = '';
                _discountController.text = '';
                _discountPercentController.text = '';
                tax = 0;
                _rateController.text = '';
                _serialNoController.text = '';
                discount = 0;
                discountPercent = 0;
                subTotal = 0;
                total = 0;
                gross = 0;
                selectedColor = null;
                selectedSize = null;
                var datas = api.fetchNoStockVariantList(selectedItem.code,taxGroupUpdate,lId).then((value) {
                  setState(() {
                    isLoading = false;
                  });
                  return showSherTexItemDialog(context, value, isSerialNoInStockVariant, selectedItem.name, selectedItem.quantity, []);
                });
              } catch (e) {
                setState(() {
                  isLoading = false;
                });
                ScaffoldMessenger.of(context).showSnackBar(
                  SnackBar(content: Text('Error fetching no stock variants: ${e.toString()}')),
                );
              }
            }
          } else {
            if (selectedItem.hasVariant) {
              setState(() {
                isLoading = true;
              });
              try {
                itemNameControl.text = selectedItem.name!;
                selectedVariant = null;
                _dropDownUnit = 0;
                rate = 0;
                quantity = 0;
                _quantityController.text = '';
                _discountController.text = '';
                _discountPercentController.text = '';
                tax = 0;
                _rateController.text = '';
                _serialNoController.text = '';
                discount = 0;
                discountPercent = 0;
                subTotal = 0;
                total = 0;
                gross = 0;
                selectedColor = null;
                selectedSize = null;
                
                var datas = api.fetchStockVariantList(selectedItemId!,taxGroupUpdate,lId).then((value) {
                  setState(() {
                    isLoading = false;
                  });
                  if (keyItemsVariantStock && !sherTex) {
                    selectedTaxOption = salesTypeData!.tax ? 'With Tax' : 'Without Tax';
                    isTax = selectedTaxOption == 'With Tax' ? true : false;
                    
                    fetchProductDetails(selectedItem.name);
                    showItemDialog(context, value, isSerialNoInStockVariant, selectedItem.name, selectedItem.quantity);
                  } else if (sherTex) {
                    showSherTexItemDialog(context, value, isSerialNoInStockVariant, selectedItem.name, selectedItem.quantity, []);
                  } else {
                    itemVarianDetails(selectedItem);
                    fetchProductDetails(selectedItem.name);
                  }
                }).catchError((error) {
                  setState(() {
                    isLoading = false;
                  });
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(content: Text('Error fetching stock variants: ${error.toString()}')),
                  );
                });
              } catch (e) {
                setState(() {
                  isLoading = false;
                });
                ScaffoldMessenger.of(context).showSnackBar(
                  SnackBar(content: Text('Error: ${e.toString()}')),
                );
              }
            } else {
              setState(() {
                isLoading = true;
              });
              try {
                itemNameControl.text = selectedItem.name!;
                selectedVariant = null;
                _dropDownUnit = 0;
                rate = 0;
                quantity = 0;
                _quantityController.text = '';
                _discountController.text = '';
                _discountPercentController.text = '';
                tax = 0;
                _rateController.text = '';
                discount = 0;
                discountPercent = 0;
                subTotal = 0;
                total = 0;
                gross = 0;
                selectedColor = null;
                selectedSize = null;
                
                itemVarianDetails(selectedItem);
                setState(() {
                  isLoading = false;
                  if (isQuantityBasedSerialNo) {
                    fetchProductDetails(selectedItem.name);
                  }
                });
              } catch (e) {
                setState(() {
                  isLoading = false;
                });
                ScaffoldMessenger.of(context).showSnackBar(
                  SnackBar(content: Text('Error: ${e.toString()}')),
                );
              }
            }
          }
        },
      ),
    ),
    onDoubleTap: () {
      if (selectedItem != null) {
        if (sherTex) {
          if (selectedItem.quantity > 0) {
            setState(() {
              _isLoading = true;
            });
            var newValue;
            _dropDownUnit = 0;
            rate = 0;
            quantity = 0;
            _quantityController.text = '';
            _discountController.text = '';
            _discountPercentController.text = '';
            tax = 0;
            _rateController.text = '';
            _serialNoController.text = '';
            discount = 0;
            discountPercent = 0;
            subTotal = 0;
            total = 0;
            gross = 0;
            selectedColor = null;
            selectedSize = null;
            var datas = api.fetchStockVariantList(selectedItemId!,taxGroupUpdate,lId).then((value) {
              setState(() {
                _isLoading = false;
              });
              return showSherTexItemDialog(context, value, isSerialNoInStockVariant, selectedItem.name, selectedItem.quantity, []);
            });
          } else {
            setState(() {
              _isLoading = true;
            });
            var newValue;
            _dropDownUnit = 0;
            rate = 0;
            quantity = 0;
            _quantityController.text = '';
            _discountController.text = '';
            _discountPercentController.text = '';
            tax = 0;
            _rateController.text = '';
            _serialNoController.text = '';
            discount = 0;
            discountPercent = 0;
            subTotal = 0;
            total = 0;
            gross = 0;
            selectedColor = null;
            selectedSize = null;
            var datas = api.fetchNoStockVariantList(selectedItem.code,taxGroupUpdate,lId).then((value) {
              setState(() {
                _isLoading = false;
              });
              return showSherTexItemDialog(context, value, isSerialNoInStockVariant, selectedItem.name, selectedItem.quantity, []);
            });
          }
        }
      } else if (editItem && sherTex) {
        setState(() {
          _isLoading = true;
        });
        var newValue;
        _dropDownUnit = 0;
        rate = 0;
        quantity = 0;
        _quantityController.text = '';
        _discountController.text = '';
        _discountPercentController.text = '';
        tax = 0;
        _rateController.text = '';
        _serialNoController.text = '';
        discount = 0;
        discountPercent = 0;
        subTotal = 0;
        total = 0;
        gross = 0;
        selectedColor = null;
        selectedSize = null;
        var datas = api.fetchStockVariantList(selectedVariant!.itemId!,taxGroupUpdate,lId).then((value) {
          setState(() {
            _isLoading = false;
          });
          if (selectedData != null && selectedData!.isNotEmpty) {
            for (var selectedItem in selectedData!) {
              for (var itm in value) {
                if (itm.productId == selectedItem.productId) {
                  selectedItem.color ??= itm.color;
                  selectedItem.size ??= itm.size;
                  selectedItem.quantity ??= itm.quantity;
                  selectedItem.sellingPrice ??= itm.sellingPrice;
                  selectedItem.wholeSalePrice ??= itm.wholeSalePrice;
                  selectedItem.retailPrice ??= itm.retailPrice;
                  selectedItem.spRetailPrice ??= itm.spRetailPrice;
                  selectedItem.adCessPer ??= itm.adCessPer;
                  selectedItem.branch ??= itm.branch;
                  selectedItem.brand ??= itm.brand;
                  selectedItem.buyingPrice ??= itm.buyingPrice;
                  selectedItem.buyingPriceReal ??= itm.buyingPriceReal;
                  selectedItem.categoryId ??= itm.categoryId;
                  selectedItem.cess ??= itm.cess;
                  selectedItem.cessPer ??= itm.cessPer;
                  selectedItem.company ??= itm.company;
                  selectedItem.estUniqueCode ??= itm.estUniqueCode;
                  selectedItem.expDate ??= itm.expDate;
                  selectedItem.free ??= itm.free;
                  selectedItem.hsnCode ??= itm.hsnCode;
                  selectedItem.itemId ??= itm.itemId;
                  selectedItem.locationId ??= itm.locationId;
                  selectedItem.locked ??= itm.locked;
                  selectedItem.mfrId ??= itm.mfrId;
                  selectedItem.minimumRate ??= itm.minimumRate;
                  selectedItem.name ??= itm.name;
                  selectedItem.oBarcode ??= itm.oBarcode;
                  selectedItem.productId ??= itm.productId;
                  selectedItem.rackId ??= itm.rackId;
                  selectedItem.serialNo ??= itm.serialNo;
                  selectedItem.stockValuation ??= itm.stockValuation;
                  selectedItem.subcategoryId ??= itm.subcategoryId;
                  selectedItem.supplierId ??= itm.supplierId;
                  selectedItem.tax ??= itm.tax;
                  selectedItem.taxType ??= itm.taxType;
                  selectedItem.unitId ??= itm.unitId;
                }
              }
            }
          }
          return showSherTexItemDialog(context, value, isSerialNoInStockVariant, selectedVariant!.name!, selectedVariant!.quantity!, selectedData);
        });
      }
    },
  );
}

