Widget nameWiseTexSimpleFieldWithGridView() {
  final FocusNode _focusNode = FocusNode();
  bool _loadedDefaultItems = false;  // Added missing variable
  bool _initialFocus = true;  // Added missing variable
  
  return StatefulBuilder(
    builder: (context, localSetState) {  // Renamed setState to localSetState
      bool showOptions = false;
      
      // Function to load default items with a default search term
      Future<void> _loadDefaultItems() async {
        try {
          // Use a default search term 'a' to pre-populate the dropdown
          _rawInputText = 'a';
          itemNameLike = 'a';
          
          // We're simulating a search with 'a' to show default items
          // but not actually changing the text field's content
          debugPrint('Loading default items with search term: a');
          
          // This will trigger the dropdown to show with results from searching 'a'
          // We're just manually triggering the same API call that would happen when typing
          if (salesTypeData?.type == 'SALES-O' || salesTypeData?.type == 'SALES-Q') {
            !isStockProductOnlyInSalesQO
              ? await api.fetchStockProductLike(DateUtil.dateDMY2YMD(formattedDate), 'a')
              : await api.fetchNoStockProductLike(DateUtil.dateDMY2YMD(formattedDate), 'a');
          } else {
            await api.fetchStockProductLike(DateUtil.dateDMY2YMD(formattedDate), 'a');
          }
        } catch (e) {
          debugPrint('Error loading default items: $e');
        }
      }
      
      return RawAutocomplete<StockItem>(
        textEditingController: itemNameControl,
        focusNode: _focusNode,
        optionsBuilder: (TextEditingValue textEditingValue) async {
          // If text is empty and we're on initial focus, use default search term 'a'
          String searchText;
          if (textEditingValue.text.isEmpty && _initialFocus) {
            searchText = 'a'; // Default search term
          } else {
            searchText = textEditingValue.text;
          }
          
          // Don't search with empty text when not on initial focus
          if (searchText.isEmpty && !_initialFocus) {
            return const Iterable<StockItem>.empty();
          }
          
          _rawInputText = searchText;
          itemNameLike = searchText;
          
          try {
            if (salesTypeData?.type == 'SALES-O' || salesTypeData?.type == 'SALES-Q') {
              return !isStockProductOnlyInSalesQO
                ? await api.fetchStockProductLike(DateUtil.dateDMY2YMD(formattedDate), itemNameLike)
                : await api.fetchNoStockProductLike(DateUtil.dateDMY2YMD(formattedDate), itemNameLike);
            } else {
              return await api.fetchStockProductLike(DateUtil.dateDMY2YMD(formattedDate), itemNameLike);
            }
          } catch (e) {
            debugPrint('Error fetching autocomplete options: $e');
            return const Iterable<StockItem>.empty();
          }
        },
        displayStringForOption: (StockItem option) =>
            itemCodeViseChek ? option.code ?? '' : option.name ?? '',
        optionsViewBuilder: (context, onSelected, options) {
          final items = options.toList();
          
          if (items.isEmpty) {
            return const SizedBox.shrink();
          }

          return Align(
            alignment: Alignment.topLeft,
            child: Material(
              elevation: 4.0,
              child: ConstrainedBox(
                constraints: BoxConstraints(
                  // maxHeight: 350,
                  maxWidth: MediaQuery.of(context).size.width * 0.90,
                ),
                child: items.isEmpty
                  ? const Center(child: Padding(
                      padding: EdgeInsets.all(16.0),
                      child: Text('No items found'),
                    ))
                  : GridView.builder(
                    shrinkWrap: true,
                    physics: const ClampingScrollPhysics(),
                    padding: const EdgeInsets.all(8),
                    itemCount: items.length,
                    gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                      crossAxisCount: 2,
                      childAspectRatio: .98,
                      crossAxisSpacing: 8,
                      mainAxisSpacing: 8,
                    ),
                    itemBuilder: (context, index) {
                      final item = items[index];
                      final imageUrl = "https://imageupload.blackbaton.com/uploads/${item.id}.jpg";
                      final displayText = itemCodeViseChek ? item.code : item.name;
                      final itemQuantity = "Qty: ${item.quantity}";

                      return InkWell(
                        onTap: () => onSelected(item),
                        child: Container(
                          decoration: BoxDecoration(
                            color: Colors.white,
                            border: Border.all(color: Colors.grey),
                            borderRadius: BorderRadius.circular(5),
                            boxShadow: [
                              BoxShadow(
                                color: Colors.grey.withOpacity(0.2),
                                spreadRadius: 1,
                                blurRadius: 3,
                                offset: const Offset(0, 2),
                              )
                            ],
                          ),
                          child: Column(
                            children: [
                              Expanded(
                                flex: 3,
                                child: Image.network(
                                  imageUrl,
                                  fit: BoxFit.fill,
                                  width: double.infinity,
                                  errorBuilder: (_, __, ___) => Container(
                                    color: Colors.grey[200],
                                    child: const Icon(Icons.image_not_supported),
                                  ),
                                  loadingBuilder: (_, child, loadingProgress) {
                                    if (loadingProgress == null) return child;
                                    return Center(
                                      child: CircularProgressIndicator(
                                        value: loadingProgress.expectedTotalBytes != null
                                            ? loadingProgress.cumulativeBytesLoaded /
                                                loadingProgress.expectedTotalBytes!
                                            : null,
                                      ),
                                    );
                                  },
                                ),
                              ),
                              Expanded(
                                flex: 2,
                                child: Padding(
                                  padding: const EdgeInsets.all(4.0),
                                  child: Column(
                                    children: [
                                      Text(
                                        displayText ?? '',
                                        style: const TextStyle(fontSize: 12),
                                        overflow: TextOverflow.ellipsis,
                                        textAlign: TextAlign.center,
                                        maxLines: 2,
                                      ),
                                      const SizedBox(height: 2),
                                      Text(
                                        itemQuantity,
                                        style: const TextStyle(fontSize: 10, color: Colors.grey),
                                      ),
                                    ],
                                  ),
                                ),
                              ),
                            ],
                          ),
                        ),
                      );
                    },
                  ),
              ),
            ),
          );
        },
        onSelected: (StockItem selectedItem) async {
          debugPrint("Selected Item: ${selectedItem.name}");
          itemNameLike = _rawInputText;

          itemNameControl.text = selectedItem.name!;
          selectedItemId = selectedItem.id;
          selectedItemCode = selectedItem.code;

          localSetState(() => this.selectedItem = selectedItem);  // Changed setState to localSetState

          // Handle logic just like in your original onSelected
          if (sherTex) {
            localSetState(() => isLoading = true);  // Changed setState to localSetState
            if (selectedItem.quantity! > 0) {
              final variants = await api.fetchStockVariantList(selectedItem.id!,taxGroupUpdate,lId);
              showSherTexItemDialog(context, variants, isSerialNoInStockVariant,
                  selectedItem.name!, selectedItem.quantity!, []);
            } else {
              final variants = await api.fetchNoStockVariantList(selectedItem.code!,taxGroupUpdate,lId);
              showSherTexItemDialog(context, variants, isSerialNoInStockVariant,
                  selectedItem.name!, selectedItem.quantity!, []);
            }
          } else {
            if (selectedItem.hasVariant!) {
              localSetState(() => isLoading = true);  // Changed setState to localSetState
              final variants = await api.fetchStockVariantList(selectedItem.id!,taxGroupUpdate,lId);
              _resetFormFields();

              if (keyItemsVariantStock && !sherTex) {
                selectedTaxOption = salesTypeData!.tax ? 'With Tax' : 'Without Tax';
                isTax = selectedTaxOption == 'With Tax';
                fetchProductDetails(selectedItem.name!);
                showItemDialog(
                    context, variants, isSerialNoInStockVariant, selectedItem.name!, selectedItem.quantity!);
              } else if (sherTex) {
                showSherTexItemDialog(context, variants, isSerialNoInStockVariant,
                    selectedItem.name!, selectedItem.quantity!, []);
              } else {
                itemVarianDetails(selectedItem);
                fetchProductDetails(selectedItem.name!);
              }
            } else {
              _resetFormFields();
              itemVarianDetails(selectedItem);
              if (isQuantityBasedSerialNo) {
                fetchProductDetails(selectedItem.name!);
              }
            }
          }
        },
        fieldViewBuilder: (context, controller, focusNode, onFieldSubmitted) {
          // Force initial focus and loading
          WidgetsBinding.instance.addPostFrameCallback((_) {
            // Show options dropdown automatically on initialization
            // This happens only once due to the _loadedDefaultItems flag
            if (!_loadedDefaultItems) {
              _loadedDefaultItems = true;
              _loadDefaultItems().then((_) {
                // Ensure the text field is focused to show options
                if (!focusNode.hasFocus && focusNode.canRequestFocus) {
                  focusNode.requestFocus();
                  localSetState(() {}); // Refresh UI
                }
              });
            }
          });
          
          return TextFormField(
            controller: controller,
            focusNode: focusNode,
            decoration: InputDecoration(
              border: OutlineInputBorder(borderRadius: BorderRadius.circular(5)),
              hintText: 'Enter product name',
              suffixIcon: IconButton(
                icon: const Icon(Icons.clear),
                onPressed: () {
                  controller.clear();
                  // Reset to show default items and trigger a refresh
                  focusNode.requestFocus(); // Keep focus after clearing
                  localSetState(() {
                    _initialFocus = true; // Reset to show default items
                    
                    // Force refresh of options by notifying listeners
                    // This will trigger optionsBuilder with empty text + _initialFocus = true
                    controller.notifyListeners();
                  });
                },
              ),
            ),
            onTap: () {
              // Show options on first tap even without typing
              if (!focusNode.hasFocus) {
                focusNode.requestFocus();
                // Force refresh options and set initial focus to true to trigger default search
                localSetState(() {
                  _initialFocus = true;
                  
                  // Trigger a refresh of options by simulating a text change
                  // This will use our default 'a' search in optionsBuilder
                  if (controller.text.isEmpty) {
                    // Force the RawAutocomplete to rebuild and fetch options
                    // This will show options with default search term
                    controller.notifyListeners();
                  }
                });
              }
            },
            onChanged: (value) {
              // When user starts typing, we're no longer on initial focus
              localSetState(() {
                if (value.isNotEmpty) {
                  _initialFocus = false;
                }
              });
            },
            onFieldSubmitted: (value) {
              onFieldSubmitted();
            },
          );
        },
      );
    }
  );
}

 void _resetFormFields() {
  _dropDownUnit = 0;
  rate = 0;
  quantity = 0;
  tax = 0;
  discount = 0;
  discountPercent = 0;
  subTotal = 0;
  total = 0;
  gross = 0;
  selectedColor = null;
  selectedSize = null;

  _quantityController.text = '';
  _discountController.text = '';
  _discountPercentController.text = '';
  _rateController.text = '';
  _serialNoController.text = '';
}


