   Map<String, List<dynamic>> colorGroups = {};
   bool allColorsSelected = false; 
    selectedData = initialSelectedData ?? [];
  
  if (initialSelectedData != null) {
    for (var item in initialSelectedData) {
      // Add to selectedColors
