      selectedVariantTex = null;
      selectedSizesForColor.clear();
      selectedColors.clear();
      colorGroups.clear();
      sizeQuantities.clear();
      debugPrint(colorGroups.toString());
      debugPrint(selectedColors.toString());
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('No Variant selected'),
        ),
      );
    }
  });
}

