  void addProduct(product, int index) {
  // If isFreeItem is false, find the index of the product in cartItem based on uniqueCode
  if (!isFreeItem) {
    if(sherTex){
      index = -1;
    }else{
      index =
     cartItem.indexWhere((i) => i.uniqueCode == product.uniqueCode);
    }
  }
  

  if (index != -1) {
    // Update product if it already exists in the cart
    updateProduct(
        product, cartItem[index].quantity! + product.quantity, index);
  } else {
    // Add the product to the cart if it doesn't exist
    cartItem.add(product);
    calculateTotal(); // Recalculate the total after adding the product
  }
}


