  void clearCart() {
    for (var f in cartItem) {
      f.quantity = 1;
    }
    setState(() {
      // controllerNarration.text = '';
      // returnEntryNoController.text = '';
      // returnAmountController.text = '';
      // returnAmount = 0;
      // otherAmountList = [];
      // controllerCashReceived.text = '';
      selectedCashCustomerId = 0;
      selectedCustomerId = 0;
      selectedCustomer = '';
      customerNameControl.text = '';
      cartItem = [];
      calculateTotal();
      
    });
  }

  void calculateTotal() {
    totalGrossValue = 0;
    totalDiscount = 0;
    totalRDiscount = 0;
    totalNet = 0;
    totalCess = 0;
    totalIgST = 0;
    totalCgST = 0;
    totalSgST = 0;
    totalFCess = 0;
    totalAdCess = 0;
    taxTotalCartValue = 0;
    totalCartValue = 0;
    totalProfit = 0;
    grandTotal = 0;

    for (var f in cartItem) {
      totalGrossValue += f.gross!;
      totalDiscount += f.discount!;
      totalRDiscount += f.rDiscount!;
      totalNet += f.net!;
      totalCess += f.cess!;
      totalIgST += f.iGST!;
      totalCgST += f.cGST!;
      totalSgST += f.sGST!;
      totalFCess += f.fCess!;
      totalAdCess += f.adCess!;
      taxTotalCartValue += f.tax!;
      totalCartValue += f.total!;
      totalProfit += f.profitPer!;
    }
    grandTotal = (totalCartValue - returnAmount) +
        otherAmountList.fold(
            0.0,
            (t, e) =>
                t +
                double.parse(e['Symbol'] == '-'
                    ? (e['Amount'] * -1).toString()
                    : e['Amount'].toString()));
  }

