  Future<XFile> bufferToXFile(Map<String, dynamic> bufferData, String fileName) async {
  try {
    if (bufferData['type'] == 'Buffer' && bufferData['data'] is List) {
      List<int> bytes = List<int>.from(bufferData['data']);
      
      final directory = await getTemporaryDirectory();
      final filePath = '${directory.path}/$fileName.png';
      
      final file = File(filePath);
      await file.writeAsBytes(bytes);
      
      return XFile(filePath);
    }
    return XFile('');
  } catch (e) {
    debugPrint('Error converting buffer to XFile: $e');
    return XFile('');
  }
}

  Future<void> processDeliveryItems(List deliveryItemsData) async {
  if (deliveryItemsData.isEmpty) return;

  List<DeliveryItemWiseModel> finalItems = [];

  for (var itemData in deliveryItemsData) {

    XFile img = XFile('');
    
    if (itemData.containsKey('Photo') && itemData['Photo'] is Map) {
      Map<String, dynamic> photoData = itemData['Photo'];

      if (photoData['type'] == 'Buffer' && photoData['data'] is List) {
        String fileName =
            'delivery_${itemData['Entryno']}_${itemData['itemid']}_${DateTime.now().microsecondsSinceEpoch}';

        img = await bufferToXFile(photoData, fileName);
      }
    }

    finalItems.add(
      DeliveryItemWiseModel(
        gId: itemData['Gridid'],
        entryNo: itemData['Entryno'],
        itemId: itemData['itemid'],
        image: img,
      ),
    );
  }

  // deliveryItems.clear();
  // deliveryItems.addAll(finalItems);

  // debugPrint("Loaded ${deliveryItems.length} delivery images");
}


