  Widget salesManVehicle() {
  if (salesmanAsVehicle) {
    return Row(
      children: [
        SizedBox(
          width: 120,
          // height : 47,
          child: DropdownSearch<dynamic>(
             popupProps: const PopupProps.dialog(
              showSearchBox: true,
              fit: FlexFit.loose,
              constraints: BoxConstraints(
                maxHeight: 500,
              ),
            ),
            asyncItems: (String filter) => getSalesManListData(filter),
            dropdownDecoratorProps: const DropDownDecoratorProps(
              dropdownSearchDecoration: InputDecoration(
                border: OutlineInputBorder(),
                // labelText: 'V No',
              ),
            ),
            onChanged: (dynamic data) {
              setState(() {
                vehicleData = otherRegSalesManList.firstWhere(
                  (element) => element['Auto'].toString() == data.id.toString(),
                );
                vehicleName = vehicleData['Name'];
                vehicleNameControl.text = vehicleName ?? '';
              });
            },
          ),
        ),
        const SizedBox(width: 10),
        Expanded(
          child: TextField(
            readOnly: true,
            decoration: InputDecoration(
              contentPadding: const EdgeInsets.symmetric(
                vertical: 6,
                horizontal: 4,
              ),
              border: const OutlineInputBorder(),
              label: Text(vehicleName ?? ''),
            ),
          ),
        ),
      ],
    );
  } else {
    return SimpleAutoCompleteTextField(
      key: keyVehicleName,
      controller: vehicleNameControl,
      clearOnSubmit: false,
      suggestions: vehicleNameListDisplay,
      decoration: const InputDecoration(
        contentPadding: EdgeInsets.symmetric(
          vertical: 4,
          horizontal: 4,
        ),
        border: OutlineInputBorder(),
      ),
    );
  }
}


  Future<List<dynamic>> getSalesManListData(String filter) async {
    var dd = filter.isEmpty
        ? otherRegSalesManList
        : otherRegSalesManList
            .where((element) => element['Name']
                .toString()
                .toLowerCase()
                .contains(filter.toLowerCase()))
            .toList();
    List<DataJson> dataResult = [];
    for (var data in dd) {
      dataResult.add(DataJson(
          id: data['Auto'],
          name: data['Name'].trim().split(' ')[0].toString()));
    }
    return dataResult;
  }

