  checkRefId(map) {
    if (map.containsKey('refId')) {
      return true;
    } else {
      return false;
    }
  }

  String getRefId(map) {
    if (map.containsKey('refId')) {
      if (map['refId'].toString().trim() != '0') {
        return map['refId'].toString() == 'null' ? '' : map['refId'].toString();
      } else {
        return '';
      }
    } else {
      return '';
    }
  }

  void fetchProductDetails(String pItemName) {
    api.getProductByName(pItemName).then((value) {
      if (value != null) {
        if (value.slno > 0) {
          isSerialNoItem = value.serialno > 0 ? true : false;
        }
      }
    });
  }
  
